{
  "name": "Mile High Limo Navigator",
  "description": "A professional-grade routing and traffic monitoring app for Colorado limo drivers, powered by Gemini with Google Maps grounding for real-time traffic and incident awareness.",
  "requestFramePermissions": [
    "geolocation"
  ]
}

export interface Location {
  latitude: number;
  longitude: number;
}

export interface GroundingChunk {
  maps?: {
    uri: string;
    title: string;
  };
}

export interface RouteResponse {
  text: string;
  sources: { title: string; url: string }[];
  timestamp: string;
}

export interface TrafficIncident {
  id: string;
  type: 'accident' | 'traffic' | 'weather';
  location: string;
  severity: 'low' | 'medium' | 'high';
  description: string;
}

import { GoogleGenAI } from "@google/genai";
import { Location, RouteResponse } from "../types";

export class GeminiService {
  private ai: GoogleGenAI;

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
  }

  async getBestRoute(
    origin: string,
    destination: string,
    currentLocation?: Location
  ): Promise<RouteResponse> {
    const prompt = `As an expert Colorado limo navigator, analyze the current traffic and accidents between "${origin}" and "${destination}". 
    Consider that I am driving a luxury limousine and need the smoothest, most efficient route. 
    Check for current I-70 or I-25 incidents, construction, and weather-related delays in Colorado.
    Provide a concise summary of the best route and any specific warnings.`;

    try {
      const config: any = {
        tools: [{ googleMaps: {} }],
      };

      if (currentLocation) {
        config.toolConfig = {
          retrievalConfig: {
            latLng: {
              latitude: currentLocation.latitude,
              longitude: currentLocation.longitude,
            },
          },
        };
      }

      const response = await this.ai.models.generateContent({
        model: "gemini-2.5-flash",
        contents: prompt,
        config: config,
      });

      const text = response.text || "Unable to retrieve route data.";
      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];

      const sources = chunks
        .filter((chunk: any) => chunk.maps)
        .map((chunk: any) => ({
          title: chunk.maps.title,
          url: chunk.maps.uri,
        }));

      return {
        text,
        sources,
        timestamp: new Date().toLocaleTimeString(),
      };
    } catch (error) {
      console.error("Gemini API Error:", error);
      throw new Error("Failed to fetch traffic data. Please check your connection.");
    }
  }

  async monitorColoradoTraffic(location: Location): Promise<RouteResponse> {
    const prompt = `Scan for major traffic accidents and significant delays currently affecting the Denver metro area and Colorado mountain corridors (I-70, I-25, E-470). Focus on critical updates for professional drivers.`;

    try {
      const response = await this.ai.models.generateContent({
        model: "gemini-2.5-flash",
        contents: prompt,
        config: {
          tools: [{ googleMaps: {} }],
          toolConfig: {
            retrievalConfig: {
              latLng: location,
            },
          },
        },
      });

      const text = response.text || "No major incidents reported.";
      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];

      const sources = chunks
        .filter((chunk: any) => chunk.maps)
        .map((chunk: any) => ({
          title: chunk.maps.title,
          url: chunk.maps.uri,
        }));

      return {
        text,
        sources,
        timestamp: new Date().toLocaleTimeString(),
      };
    } catch (error) {
      console.error("Gemini Monitor Error:", error);
      throw new Error("Failed to monitor traffic.");
    }
  }
}

import React, { useState, useEffect, useRef } from 'react';
import { GeminiService } from '../services/geminiService';
import { Location, RouteResponse } from '../types';

const Dashboard: React.FC = () => {
  const [origin, setOrigin] = useState('Denver International Airport');
  const [destination, setDestination] = useState('Downtown Denver');
  const [loading, setLoading] = useState(false);
  const [routeResult, setRouteResult] = useState<RouteResponse | null>(null);
  const [location, setLocation] = useState<Location | null>(null);
  const [trafficFeed, setTrafficFeed] = useState<RouteResponse | null>(null);
  const gemini = useRef(new GeminiService());

  useEffect(() => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (pos) => setLocation({ latitude: pos.coords.latitude, longitude: pos.coords.longitude }),
        (err) => console.warn("Location access denied", err)
      );
    }
  }, []);

  const handleRouteRequest = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      const result = await gemini.current.getBestRoute(origin, destination, location || undefined);
      setRouteResult(result);
    } catch (error) {
      alert("Error calculating route. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const handleRefreshTraffic = async () => {
    if (!location) return;
    setLoading(true);
    try {
      const feed = await gemini.current.monitorColoradoTraffic(location);
      setTrafficFeed(feed);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex flex-col lg:flex-row h-screen w-full bg-[#0f172a] overflow-hidden">
      {/* Sidebar - Route Planning */}
      <div className="w-full lg:w-96 glass p-6 flex flex-col gap-6 z-10 shadow-2xl">
        <div className="flex items-center gap-3 mb-4">
          <div className="bg-amber-500 p-2 rounded-lg">
            <i className="fas fa-limousine text-slate-900 text-xl"></i>
          </div>
          <h1 className="text-xl font-bold text-white tracking-tight">MILE HIGH NAV</h1>
        </div>

        <form onSubmit={handleRouteRequest} className="flex flex-col gap-4">
          <div className="flex flex-col gap-1">
            <label className="text-xs font-semibold text-slate-400 uppercase tracking-wider">Starting From</label>
            <div className="relative">
              <i className="fas fa-circle-dot absolute left-3 top-1/2 -translate-y-1/2 text-green-500 text-xs"></i>
              <input 
                type="text" 
                value={origin}
                onChange={(e) => setOrigin(e.target.value)}
                className="w-full bg-slate-800/50 border border-slate-700 rounded-lg py-2.5 pl-9 pr-4 text-sm focus:outline-none focus:ring-2 focus:ring-amber-500/50 transition-all"
                placeholder="Origin..."
              />
            </div>
          </div>

          <div className="flex flex-col gap-1">
            <label className="text-xs font-semibold text-slate-400 uppercase tracking-wider">Destination</label>
            <div className="relative">
              <i className="fas fa-location-dot absolute left-3 top-1/2 -translate-y-1/2 text-red-500 text-xs"></i>
              <input 
                type="text" 
                value={destination}
                onChange={(e) => setDestination(e.target.value)}
                className="w-full bg-slate-800/50 border border-slate-700 rounded-lg py-2.5 pl-9 pr-4 text-sm focus:outline-none focus:ring-2 focus:ring-amber-500/50 transition-all"
                placeholder="Destination..."
              />
            </div>
          </div>

          <button 
            type="submit"
            disabled={loading}
            className={`mt-2 w-full bg-amber-500 hover:bg-amber-400 text-slate-900 font-bold py-3 rounded-lg flex items-center justify-center gap-2 transition-all shadow-lg shadow-amber-500/20 ${loading ? 'opacity-50 cursor-not-allowed' : ''}`}
          >
            {loading ? <i className="fas fa-circle-notch fa-spin"></i> : <i className="fas fa-route"></i>}
            GET ELITE ROUTE
          </button>
        </form>

        <div className="mt-6 flex flex-col gap-3">
          <h2 className="text-xs font-semibold text-slate-400 uppercase tracking-wider">Professional Presets</h2>
          <div className="grid grid-cols-1 gap-2">
            {[
              ['DIA', 'Cherry Creek'],
              ['Downtown', 'Aspen'],
              ['Boulder', 'Vail'],
              ['Union Station', 'Red Rocks']
            ].map(([start, end]) => (
              <button 
                key={`${start}-${end}`}
                onClick={() => { setOrigin(start); setDestination(end); }}
                className="text-left text-sm py-2 px-3 rounded bg-slate-800/30 hover:bg-slate-700/50 border border-slate-700/50 transition-all flex justify-between items-center group"
              >
                <span className="text-slate-300 group-hover:text-white">{start} <i className="fas fa-arrow-right mx-1 text-[10px] text-slate-500"></i> {end}</span>
                <i className="fas fa-chevron-right text-[10px] text-amber-500/50"></i>
              </button>
            ))}
          </div>
        </div>

        <div className="mt-auto pt-6 border-t border-slate-700/50 text-[10px] text-slate-500 flex justify-between items-center">
          <span>CO DRIVER PORTAL v2.5</span>
          <span className="flex items-center gap-1">
            <span className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse"></span>
            LIVE RADAR ACTIVE
          </span>
        </div>
      </div>

      {/* Main Content Area */}
      <div className="flex-1 relative flex flex-col">
        {/* Header Overlay */}
        <div className="absolute top-0 left-0 right-0 p-4 z-10 flex justify-between items-start pointer-events-none">
          <div className="flex flex-col gap-2 pointer-events-auto">
            <div className="glass px-4 py-2 rounded-full flex items-center gap-3 shadow-lg">
              <i className="fas fa-satellite text-amber-500"></i>
              <span className="text-sm font-medium tracking-wide">
                {location ? `${location.latitude.toFixed(4)}, ${location.longitude.toFixed(4)}` : 'Awaiting GPS...'}
              </span>
            </div>
          </div>
          <button 
            onClick={handleRefreshTraffic}
            className="pointer-events-auto glass px-4 py-2 rounded-full flex items-center gap-2 hover:bg-white/10 transition-all shadow-lg text-sm font-medium"
          >
            <i className={`fas fa-sync-alt ${loading ? 'animate-spin' : ''}`}></i>
            SCAN AREA
          </button>
        </div>

        {/* Visual Background / Map Area */}
        <div className="flex-1 bg-slate-900 relative overflow-hidden flex items-center justify-center">
          {/* Stylized Grid for 'Tech' Feel */}
          <div className="absolute inset-0 opacity-20 pointer-events-none" 
               style={{backgroundImage: 'radial-gradient(#475569 1px, transparent 1px)', backgroundSize: '40px 40px'}}></div>

          <div className="text-center p-12 max-w-2xl relative z-0">
            {!routeResult && !trafficFeed && (
              <div className="flex flex-col items-center gap-6 opacity-40">
                <i className="fas fa-compass text-9xl text-slate-700"></i>
                <div>
                  <h3 className="text-2xl font-light italic">Waiting for Dispatch Instructions</h3>
                  <p className="text-sm mt-2">Enter an origin and destination to calculate the safest, fastest route in Colorado.</p>
                </div>
              </div>
            )}

            {/* Display Results */}
            {(routeResult || trafficFeed) && (
              <div className="flex flex-col gap-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
                {routeResult && (
                  <div className="text-left glass rounded-2xl p-6 shadow-2xl border-l-4 border-amber-500">
                    <div className="flex justify-between items-center mb-4">
                      <span className="bg-amber-500/10 text-amber-500 text-[10px] font-bold px-2 py-1 rounded uppercase tracking-widest">Route Analysis</span>
                      <span className="text-[10px] text-slate-500">{routeResult.timestamp}</span>
                    </div>
                    <div className="prose prose-invert text-slate-200 text-sm leading-relaxed whitespace-pre-wrap">
                      {routeResult.text}
                    </div>
                    {routeResult.sources.length > 0 && (
                      <div className="mt-4 pt-4 border-t border-slate-700/50 flex flex-wrap gap-2">
                        {routeResult.sources.map((src, i) => (
                          <a key={i} href={src.url} target="_blank" rel="noopener noreferrer" className="flex items-center gap-1.5 px-3 py-1 bg-blue-500/10 hover:bg-blue-500/20 text-blue-400 text-xs rounded transition-all">
                            <i className="fas fa-external-link-alt text-[10px]"></i>
                            {src.title}
                          </a>
                        ))}
                      </div>
                    )}
                  </div>
                )}

                {trafficFeed && (
                  <div className="text-left glass rounded-2xl p-6 shadow-2xl border-l-4 border-blue-500">
                    <div className="flex justify-between items-center mb-4">
                      <span className="bg-blue-500/10 text-blue-500 text-[10px] font-bold px-2 py-1 rounded uppercase tracking-widest">Traffic Scan</span>
                      <span className="text-[10px] text-slate-500">{trafficFeed.timestamp}</span>
                    </div>
                    <div className="prose prose-invert text-slate-200 text-sm leading-relaxed">
                      {trafficFeed.text}
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>

          {/* Floating UI Elements */}
          <div className="absolute bottom-6 left-6 right-6 flex justify-between gap-4">
            <div className="glass px-4 py-3 rounded-xl flex items-center gap-4 shadow-xl">
              <div className="flex flex-col">
                <span className="text-[10px] text-slate-500 uppercase font-bold tracking-widest">Speed Limit</span>
                <span className="text-2xl font-bold text-white">75<span className="text-xs text-slate-400 ml-1">MPH</span></span>
              </div>
              <div className="w-px h-8 bg-slate-700/50"></div>
              <div className="flex flex-col">
                <span className="text-[10px] text-slate-500 uppercase font-bold tracking-widest">I-70 Clear</span>
                <span className="text-2xl font-bold text-green-500">92%</span>
              </div>
            </div>

            <div className="glass px-4 py-3 rounded-xl flex flex-col items-end shadow-xl">
              <span className="text-[10px] text-slate-500 uppercase font-bold tracking-widest">Denver Local Time</span>
              <span className="text-2xl font-mono text-white">
                {new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
              </span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

