import { GoogleGenAI } from "@google/genai";
import { Location, RouteResponse } from "../types";

export class GeminiService {
  private ai: GoogleGenAI;

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
  }

  async getBestRoute(
    origin: string,
    destination: string,
    currentLocation?: Location
  ): Promise<RouteResponse> {
    const timeOfDay = new Date().toLocaleTimeString();
    const dayOfWeek = new Date().toLocaleDateString('en-US', { weekday: 'long' });

    const prompt = `As an elite Colorado limo navigator, analyze the route from "${origin}" to "${destination}". 
    It is currently ${dayOfWeek} at ${timeOfDay}.

    1. REAL-TIME DATA: Use Google Maps grounding to identify active accidents, construction, and heavy traffic on I-70, I-25, and local arteries.
    2. PREDICTIVE ANALYSIS: Based on historical data for this time/day, identify specific "High Risk" zones where accidents or sudden congestion are LIKELY to happen (e.g., notorious bottlenecks like The Mouse Trap, Floyd Hill, or standard commuter merge points).
    3. LIMO STANDARD: Recommend the smoothest route for passenger comfort, avoiding rough roads or heavy stop-and-go if possible.

    Format your response with a clear "RECOMMENDED ROUTE", "CURRENT INCIDENTS", and "PREDICTIVE RISK ALERTS".`;

    try {
      const config: any = {
        tools: [{ googleMaps: {} }],
      };

      if (currentLocation) {
        config.toolConfig = {
          retrievalConfig: {
            latLng: {
              latitude: currentLocation.latitude,
              longitude: currentLocation.longitude,
            },
          },
        };
      }

      const response = await this.ai.models.generateContent({
        model: "gemini-2.5-flash",
        contents: prompt,
        config: config,
      });

      const text = response.text || "Unable to retrieve route data.";
      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];

      const sources = chunks
        .filter((chunk: any) => chunk.maps)
        .map((chunk: any) => ({
          title: chunk.maps.title,
          url: chunk.maps.uri,
        }));

      return {
        text,
        sources,
        timestamp: new Date().toLocaleTimeString(),
      };
    } catch (error) {
      console.error("Gemini API Error:", error);
      throw new Error("Failed to fetch traffic data. Please check your connection.");
    }
  }

  async monitorColoradoTraffic(location: Location): Promise<RouteResponse> {
    const prompt = `Provide a high-level situational awareness report for a professional driver in Colorado. 
    Use Google Maps grounding to find current major delays. 
    ALSO, provide predictive warnings based on historical trends for current conditions (e.g., 'Friday mountain rush is building', 'High probability of ice-related accidents on Monument Hill given current temps'). 
    Highlight specific spots where drivers should expect 'ghost' traffic or high accident probabilities even if it looks clear now.`;

    try {
      const response = await this.ai.models.generateContent({
        model: "gemini-2.5-flash",
        contents: prompt,
        config: {
          tools: [{ googleMaps: {} }],
          toolConfig: {
            retrievalConfig: {
              latLng: location,
            },
          },
        },
      });

      const text = response.text || "No major incidents reported.";
      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];

      const sources = chunks
        .filter((chunk: any) => chunk.maps)
        .map((chunk: any) => ({
          title: chunk.maps.title,
          url: chunk.maps.uri,
        }));

      return {
        text,
        sources,
        timestamp: new Date().toLocaleTimeString(),
      };
    } catch (error) {
      console.error("Gemini Monitor Error:", error);
      throw new Error("Failed to monitor traffic.");
    }
  }
}

import React, { useState, useEffect, useRef } from 'react';
import { GeminiService } from '../services/geminiService';
