export interface Location {
  latitude: number;
  longitude: number;
}

export interface MapPoint {
  lat: number;
  lng: number;
  label: string;
  type: 'incident' | 'risk' | 'origin' | 'destination';
}

export interface RouteResponse {
  text: string;
  sources: { title: string; url: string }[];
  timestamp: string;
  mapData?: MapPoint[];
}

export interface TrafficIncident {
  id: string;
  type: 'accident' | 'traffic' | 'weather';
  location: string;
  severity: 'low' | 'medium' | 'high';
  description: string;
}

import { GoogleGenAI } from "@google/genai";
import { Location, RouteResponse, MapPoint } from "../types";

export class GeminiService {
  private ai: GoogleGenAI;

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
  }

  private extractMapData(text: string): MapPoint[] {
    const mapData: MapPoint[] = [];
    const regex = /\[MAP_POINT:\s*([^,]+),\s*([^,]+),\s*([^,]+),\s*([^\]]+)\]/g;
    let match;
    while ((match = regex.exec(text)) !== null) {
      mapData.push({
        lat: parseFloat(match[1]),
        lng: parseFloat(match[2]),
        label: match[3].trim(),
        type: match[4].trim() as any
      });
    }
    return mapData;
  }

  async getBestRoute(
    origin: string,
    destination: string,
    currentLocation?: Location
  ): Promise<RouteResponse> {
    const timeOfDay = new Date().toLocaleTimeString();
    const dayOfWeek = new Date().toLocaleDateString('en-US', { weekday: 'long' });

    const prompt = `As an elite Colorado limo navigator, analyze the route from "${origin}" to "${destination}". 
    It is currently ${dayOfWeek} at ${timeOfDay}.

    1. REAL-TIME DATA: Use Google Maps grounding to identify active accidents, construction, and heavy traffic on I-70, I-25, and local arteries.
    2. PREDICTIVE ANALYSIS: Identify specific "High Risk" zones where accidents or sudden congestion are LIKELY to happen based on historical patterns.
    3. LIMO STANDARD: Recommend the smoothest route.

    IMPORTANT: After your text analysis, include a special section for the map system. 
    Format each point like this: [MAP_POINT: lat, lng, label, type] 
    Where type is 'incident', 'risk', 'origin', or 'destination'. 
    Find the approximate coordinates for the origin and destination addresses provided. 
    Also include 2-3 current incident points and 2-3 risk zone points in the Colorado area related to the route.

    Format your response with "RECOMMENDED ROUTE", "CURRENT INCIDENTS", and "PREDICTIVE RISK ALERTS".`;

    try {
      const config: any = {
        tools: [{ googleMaps: {} }],
      };

      if (currentLocation) {
        config.toolConfig = {
          retrievalConfig: {
            latLng: {
              latitude: currentLocation.latitude,
              longitude: currentLocation.longitude,
            },
          },
        };
      }

      const response = await this.ai.models.generateContent({
        model: "gemini-2.5-flash",
        contents: prompt,
        config: config,
      });

      const fullText = response.text || "Unable to retrieve route data.";
      const mapData = this.extractMapData(fullText);
      const cleanedText = fullText.replace(/\[MAP_POINT:[^\]]+\]/g, '').trim();

      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
      const sources = chunks
        .filter((chunk: any) => chunk.maps)
        .map((chunk: any) => ({
          title: chunk.maps.title,
          url: chunk.maps.uri,
        }));

      return {
        text: cleanedText,
        sources,
        timestamp: new Date().toLocaleTimeString(),
        mapData
      };
    } catch (error) {
      console.error("Gemini API Error:", error);
      throw new Error("Failed to fetch traffic data.");
    }
  }

  async monitorColoradoTraffic(location: Location): Promise<RouteResponse> {
    const prompt = `Provide a situational awareness report for a professional driver in Colorado. 
    Use Google Maps grounding for current delays. Provide predictive warnings for current conditions.

    IMPORTANT: Include coordinates for map markers in the format: [MAP_POINT: lat, lng, label, type]
    Include markers for at least 5 significant traffic spots in Colorado right now. 
    Types can be 'incident' or 'risk'.`;

    try {
      const response = await this.ai.models.generateContent({
        model: "gemini-2.5-flash",
        contents: prompt,
        config: {
          tools: [{ googleMaps: {} }],
          toolConfig: {
            retrievalConfig: {
              latLng: location,
            },
          },
        },
      });

      const fullText = response.text || "No major incidents reported.";
      const mapData = this.extractMapData(fullText);
      const cleanedText = fullText.replace(/\[MAP_POINT:[^\]]+\]/g, '').trim();

      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
      const sources = chunks
        .filter((chunk: any) => chunk.maps)
        .map((chunk: any) => ({
          title: chunk.maps.title,
          url: chunk.maps.uri,
        }));

      return {
        text: cleanedText,
        sources,
        timestamp: new Date().toLocaleTimeString(),
        mapData
      };
    } catch (error) {
      console.error("Gemini Monitor Error:", error);
      throw new Error("Failed to monitor traffic.");
    }
  }
}

import React, { useState, useEffect, useRef } from 'react';
import { GeminiService } from '../services/geminiService';
import { Location, RouteResponse, MapPoint } from '../types';

declare const L: any;

const Dashboard: React.FC = () => {
  const [origin, setOrigin] = useState('Denver International Airport');
  const [destination, setDestination] = useState('Downtown Denver');
  const [loading, setLoading] = useState(false);
  const [routeResult, setRouteResult] = useState<RouteResponse | null>(null);
  const [location, setLocation] = useState<Location | null>(null);
  const [trafficFeed, setTrafficFeed] = useState<RouteResponse | null>(null);
  const gemini = useRef(new GeminiService());
  const mapRef = useRef<any>(null);
  const mapMarkers = useRef<any[]>([]);
  const mapLayers = useRef<any[]>([]);

  // Initialize Map
  useEffect(() => {
    if (!mapRef.current) {
      mapRef.current = L.map('map', {
        zoomControl: true,
        attributionControl: false
      }).setView([39.7392, -104.9903], 10); // Default to Denver

      L.tileLayer('https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png', {
        maxZoom: 19
      }).addTo(mapRef.current);
    }
  }, []);

  // Get Current Location
  useEffect(() => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (pos) => {
          const newLoc = { latitude: pos.coords.latitude, longitude: pos.coords.longitude };
          setLocation(newLoc);
          if (mapRef.current) {
            mapRef.current.setView([newLoc.latitude, newLoc.longitude], 12);
            L.circle([newLoc.latitude, newLoc.longitude], {
              color: '#10b981',
              fillColor: '#10b981',
              fillOpacity: 0.2,
              radius: 500
            }).addTo(mapRef.current);
          }
        },
        (err) => console.warn("Location access denied", err)
      );
    }
  }, []);

  const updateMapData = (points: MapPoint[]) => {
    if (!mapRef.current) return;

    // Clear old markers/layers
    mapMarkers.current.forEach(m => mapRef.current.removeLayer(m));
    mapLayers.current.forEach(l => mapRef.current.removeLayer(l));
    mapMarkers.current = [];
    mapLayers.current = [];

    const bounds = L.latLngBounds([]);

    points.forEach(point => {
      const pos = [point.lat, point.lng];
      bounds.extend(pos);

      let marker;
      if (point.type === 'incident') {
        const pulseIcon = L.divIcon({
          className: 'custom-pulse-marker',
          iconSize: [20, 20]
        });
        marker = L.marker(pos, { icon: pulseIcon }).addTo(mapRef.current);
        marker.bindPopup(`<b class="text-rose-500">ACCIDENT ALERT</b><br>${point.label}`).openPopup();
      } else if (point.type === 'risk') {
        const riskCircle = L.circle(pos, {
          color: '#f59e0b',
          fillColor: '#f59e0b',
          fillOpacity: 0.15,
          radius: 1200,
          weight: 1
        }).addTo(mapRef.current);
        riskCircle.bindPopup(`<b class="text-amber-500">PREDICTIVE RISK ZONE</b><br>${point.label}`);
        mapLayers.current.push(riskCircle);
        return;
      } else if (point.type === 'origin') {
        marker = L.circleMarker(pos, {
          radius: 8,
          fillColor: "#10b981",
          color: "#fff",
          weight: 2,
          opacity: 1,
          fillOpacity: 0.8
        }).addTo(mapRef.current);
        marker.bindPopup(`<b>PICKUP:</b> ${point.label}`);
      } else if (point.type === 'destination') {
        marker = L.marker(pos, {
          icon: L.divIcon({
            html: '<i class="fas fa-location-dot text-rose-500 text-2xl"></i>',
            className: 'bg-transparent',
            iconSize: [20, 30],
            iconAnchor: [10, 30]
          })
        }).addTo(mapRef.current);
        marker.bindPopup(`<b>DROPOFF:</b> ${point.label}`);
      }

      if (marker) mapMarkers.current.push(marker);
    });

    if (points.length > 0) {
      mapRef.current.fitBounds(bounds, { padding: [50, 50] });
    }
  };

  const handleRouteRequest = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setRouteResult(null);
    try {
      const result = await gemini.current.getBestRoute(origin, destination, location || undefined);
      setRouteResult(result);
      if (result.mapData) updateMapData(result.mapData);
    } catch (error) {
      alert("Error calculating route. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const handleRefreshTraffic = async () => {
    if (!location) return;
    setLoading(true);
    try {
      const feed = await gemini.current.monitorColoradoTraffic(location);
      setTrafficFeed(feed);
      if (feed.mapData) updateMapData(feed.mapData);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex flex-col lg:flex-row h-screen w-full bg-[#070b14] overflow-hidden text-slate-200">
      {/* Sidebar - Pro Route Planning */}
      <div className="w-full lg:w-96 glass p-6 flex flex-col gap-6 z-30 shadow-2xl overflow-y-auto scrollbar-hide relative">
        <div className="flex items-center gap-3 mb-2">
          <div className="bg-amber-500 p-2.5 rounded-xl shadow-lg shadow-amber-500/20">
            <i className="fas fa-limousine text-slate-950 text-xl"></i>
          </div>
          <div>
            <h1 className="text-xl font-black text-white tracking-tighter">MILE HIGH</h1>
            <p className="text-[10px] text-amber-500 font-bold uppercase tracking-[0.2em]">Predictive Logistics</p>
          </div>
        </div>

        <form onSubmit={handleRouteRequest} className="flex flex-col gap-5">
          <div className="space-y-4">
            <div className="flex flex-col gap-1.5">
              <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest ml-1">Dispatch Start</label>
              <div className="relative group">
                <i className="fas fa-circle-dot absolute left-3 top-1/2 -translate-y-1/2 text-emerald-500 text-[10px] group-focus-within:animate-pulse"></i>
                <input 
                  type="text" 
                  value={origin}
                  onChange={(e) => setOrigin(e.target.value)}
                  className="w-full bg-slate-900/80 border border-slate-800 rounded-xl py-3 pl-10 pr-4 text-sm focus:outline-none focus:ring-2 focus:ring-amber-500/30 transition-all"
                  placeholder="Enter pickup point..."
                />
              </div>
            </div>

            <div className="flex flex-col gap-1.5">
              <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest ml-1">Client Destination</label>
              <div className="relative group">
                <i className="fas fa-location-crosshairs absolute left-3 top-1/2 -translate-y-1/2 text-rose-500 text-[10px] group-focus-within:animate-pulse"></i>
                <input 
                  type="text" 
                  value={destination}
                  onChange={(e) => setDestination(e.target.value)}
                  className="w-full bg-slate-900/80 border border-slate-800 rounded-xl py-3 pl-10 pr-4 text-sm focus:outline-none focus:ring-2 focus:ring-amber-500/30 transition-all"
                  placeholder="Enter dropoff point..."
                />
              </div>
            </div>
          </div>

          <button 
            type="submit"
            disabled={loading}
            className={`w-full bg-gradient-to-r from-amber-600 to-amber-500 hover:from-amber-500 hover:to-amber-400 text-slate-950 font-black py-4 rounded-xl flex items-center justify-center gap-3 transition-all transform active:scale-[0.98] shadow-xl uppercase tracking-wider text-xs ${loading ? 'opacity-50' : ''}`}
          >
            {loading ? <i className="fas fa-dna fa-spin"></i> : <i className="fas fa-shield-halved"></i>}
            Analyze Smart Route
