                <span className="w-2 h-2 rounded-full bg-rose-500 animate-pulse"></span>
                <span className="font-bold text-slate-400">INCIDENT</span>
             </div>
             <div className="flex items-center gap-2 text-[10px] bg-slate-900/50 p-2 rounded-lg border border-slate-800">
                <span className="w-2 h-2 rounded-full bg-amber-500 opacity-60"></span>
                <span className="font-bold text-slate-400">RISK ZONE</span>
             </div>
          </div>
        </div>

        {/* Results Overlay inside Sidebar for better mobile use, or keep below */}
