                </div>
              )}
            </div>
          )}
        </div>

        <div className="mt-auto pt-6 border-t border-slate-800/50 text-[10px] text-slate-500 flex justify-between items-center font-bold tracking-widest">
          <span>CO DRIVER PORTAL v3.0</span>
          <span className="flex items-center gap-2">
            <span className="w-2 h-2 bg-emerald-500 rounded-full animate-ping"></span>
