export interface Location {
  latitude: number;
  longitude: number;
}

export interface MapPoint {
  lat: number;
  lng: number;
  label: string;
  type: 'incident' | 'risk' | 'origin' | 'destination' | 'enforcement';
}

export interface RouteResponse {
  text: string;
  sources: { title: string; url: string }[];
  timestamp: string;
  mapData?: MapPoint[];
}

export interface SavedRoute extends RouteResponse {
  id: string;
  origin: string;
  destination: string;
  date: string;
}

export interface TrafficIncident {
  id: string;
  type: 'accident' | 'traffic' | 'weather';
  location: string;
  severity: 'low' | 'medium' | 'high';
  description: string;
}

import React, { useState, useEffect, useRef } from 'react';
import { GeminiService } from '../services/geminiService';
import { Location, RouteResponse, MapPoint, SavedRoute } from '../types';

declare const L: any;

const FormattedAnalysis: React.FC<{ text: string }> = ({ text }) => {
  const lines = text.split('\n');

  return (
    <div className="space-y-3 break-words overflow-hidden w-full">
      {lines.map((line, idx) => {
        const trimmed = line.trim();
        if (!trimmed) return <div key={idx} className="h-1" />;

        if (trimmed.startsWith('###') || (trimmed.endsWith(':') && trimmed === trimmed.toUpperCase())) {
          const headerText = trimmed.replace(/^###\s*/, '');
          const isEnforcement = headerText.includes('ENFORCEMENT') || headerText.includes('POLICE');
          return (
            <h4 key={idx} className={`text-xs font-black uppercase tracking-[0.2em] mt-4 border-b pb-1 ${isEnforcement ? 'text-blue-500 border-blue-500/20' : 'text-amber-500 border-amber-500/10'}`}>
              {headerText}
            </h4>
          );
        }

        const numMatch = trimmed.match(/^(\d+)\.\s+(.*)/);
        if (numMatch) {
          return (
            <div key={idx} className="flex gap-3 items-start group">
              <span className="flex-shrink-0 w-5 h-5 rounded-full bg-slate-800 text-amber-500 text-[10px] font-bold flex items-center justify-center border border-slate-700 mt-0.5">
                {numMatch[1]}
              </span>
              <p className="text-[11px] leading-relaxed text-slate-300">
                {numMatch[2]}
              </p>
            </div>
          );
        }

        if (trimmed.startsWith('•') || trimmed.startsWith('-') || trimmed.startsWith('*')) {
          return (
            <div key={idx} className="flex gap-3 items-start pl-1">
              <span className="text-amber-500 mt-1 flex-shrink-0">•</span>
              <p className="text-[11px] leading-relaxed text-slate-400">
                {trimmed.replace(/^[•\-*]\s*/, '')}
              </p>
            </div>
          );
        }

        return (
          <p key={idx} className="text-[11px] leading-relaxed text-slate-300 pl-1">
            {trimmed}
          </p>
        );
      })}
    </div>
  );
};

const Dashboard: React.FC = () => {
  const [origin, setOrigin] = useState('Denver International Airport');
  const [destination, setDestination] = useState('Downtown Denver');
  const [loading, setLoading] = useState(false);
  const [routeResult, setRouteResult] = useState<RouteResponse | null>(null);
  const [location, setLocation] = useState<Location | null>(null);
  const [trafficFeed, setTrafficFeed] = useState<RouteResponse | null>(null);
  const [showMobileSidebar, setShowMobileSidebar] = useState(false);
  const [savedRoutes, setSavedRoutes] = useState<SavedRoute[]>([]);
  const [showHistory, setShowHistory] = useState(false);

  const gemini = useRef(new GeminiService());
  const mapRef = useRef<any>(null);
  const mapMarkers = useRef<any[]>([]);
  const mapLayers = useRef<any[]>([]);

  // Initialize Map
  useEffect(() => {
    if (!mapRef.current) {
      mapRef.current = L.map('map', {
        zoomControl: false,
        attributionControl: false
      }).setView([39.7392, -104.9903], 10);

      L.tileLayer('https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png', {
        maxZoom: 19
      }).addTo(mapRef.current);

      L.control.zoom({ position: 'bottomright' }).addTo(mapRef.current);
    }

    // Load saved routes
    const stored = localStorage.getItem('mile_high_routes');
    if (stored) {
      try {
        setSavedRoutes(JSON.parse(stored));
      } catch (e) {
        console.error("Failed to parse saved routes", e);
      }
    }
  }, []);

  // Get Current Location
  useEffect(() => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (pos) => {
          const newLoc = { latitude: pos.coords.latitude, longitude: pos.coords.longitude };
          setLocation(newLoc);
          if (mapRef.current) {
            mapRef.current.setView([newLoc.latitude, newLoc.longitude], 12);
            L.circle([newLoc.latitude, newLoc.longitude], {
              color: '#10b981',
              fillColor: '#10b981',
              fillOpacity: 0.2,
              radius: 500
            }).addTo(mapRef.current);
          }
        },
        (err) => console.warn("Location access denied", err)
      );
    }
  }, []);

  const updateMapData = (points: MapPoint[]) => {
    if (!mapRef.current) return;

    mapMarkers.current.forEach(m => mapRef.current.removeLayer(m));
    mapLayers.current.forEach(l => mapRef.current.removeLayer(l));
    mapMarkers.current = [];
    mapLayers.current = [];

    const bounds = L.latLngBounds([]);

    points.forEach(point => {
      const pos = [point.lat, point.lng];
      bounds.extend(pos);

      let marker;
      if (point.type === 'incident') {
        const pulseIcon = L.divIcon({
          className: 'custom-pulse-marker',
          iconSize: [14, 14],
          iconAnchor: [7, 7]
        });
        marker = L.marker(pos, { icon: pulseIcon }).addTo(mapRef.current);
        marker.bindPopup(`<div class="p-1"><b class="text-rose-500 block mb-1">ACCIDENT ALERT</b><span class="text-slate-700 text-xs">${point.label}</span></div>`);
      } else if (point.type === 'enforcement') {
        const policeIcon = L.divIcon({
          className: 'enforcement-pulse-marker',
          iconSize: [16, 16],
          iconAnchor: [8, 8]
        });
        marker = L.marker(pos, { icon: policeIcon }).addTo(mapRef.current);
        marker.bindPopup(`<div class="p-1"><b class="text-blue-500 block mb-1 uppercase tracking-tighter">Police Spot</b><span class="text-slate-700 text-xs">${point.label}</span></div>`);
      } else if (point.type === 'risk') {
        const riskCircle = L.circle(pos, {
          color: '#f59e0b',
          fillColor: '#f59e0b',
          fillOpacity: 0.1,
          radius: 1500,
          weight: 1,
          dashArray: '5, 5'
        }).addTo(mapRef.current);

        const rippleIcon = L.divIcon({
          className: 'risk-ripple-marker',
          iconSize: [10, 10],
          iconAnchor: [5, 5]
        });
        const rippleMarker = L.marker(pos, { icon: rippleIcon }).addTo(mapRef.current);
        riskCircle.bindPopup(`<div class="p-1"><b class="text-amber-500 block mb-1">RISK ZONE</b><span class="text-slate-700 text-xs">${point.label}</span></div>`);
        mapLayers.current.push(riskCircle);
        mapLayers.current.push(rippleMarker);
        return;
      } else if (point.type === 'origin') {
        marker = L.circleMarker(pos, {
          radius: 8,
          fillColor: "#10b981",
          color: "#fff",
          weight: 2,
          opacity: 1,
          fillOpacity: 0.8
        }).addTo(mapRef.current);
      } else if (point.type === 'destination') {
        marker = L.marker(pos, {
          icon: L.divIcon({
            html: '<i class="fas fa-location-dot text-rose-500 text-2xl drop-shadow-md"></i>',
            className: 'bg-transparent',
            iconSize: [20, 30],
            iconAnchor: [10, 30]
          })
        }).addTo(mapRef.current);
      }

      if (marker) mapMarkers.current.push(marker);
    });

    if (points.length > 0) {
      mapRef.current.fitBounds(bounds, { padding: [40, 40], maxZoom: 14 });
    }
  };

  const handleRouteRequest = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setRouteResult(null);
    setShowMobileSidebar(false);
    try {
      const result = await gemini.current.getBestRoute(origin, destination, location || undefined);
      setRouteResult(result);
      if (result.mapData) updateMapData(result.mapData);
    } catch (error) {
      alert("Error calculating route. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const handleSaveRoute = () => {
    if (!routeResult) return;
    const newSavedRoute: SavedRoute = {
      ...routeResult,
      id: crypto.randomUUID(),
      origin,
      destination,
      date: new Date().toLocaleDateString()
    };
    const updated = [newSavedRoute, ...savedRoutes].slice(0, 10); // Keep last 10
    setSavedRoutes(updated);
    localStorage.setItem('mile_high_routes', JSON.stringify(updated));
    alert("Tactical route archived successfully.");
  };

  const loadSavedRoute = (sr: SavedRoute) => {
    setOrigin(sr.origin);
    setDestination(sr.destination);
    setRouteResult(sr);
    if (sr.mapData) updateMapData(sr.mapData);
    setShowMobileSidebar(false);
    setShowHistory(false);
  };

  const deleteSavedRoute = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    const updated = savedRoutes.filter(r => r.id !== id);
    setSavedRoutes(updated);
    localStorage.setItem('mile_high_routes', JSON.stringify(updated));
  };

  const handleRefreshTraffic = async () => {
    if (!location) return;
    setLoading(true);
    try {
      const feed = await gemini.current.monitorColoradoTraffic(location);
      setTrafficFeed(feed);
      if (feed.mapData) updateMapData(feed.mapData);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex h-screen w-full bg-[#070b14] overflow-hidden text-slate-200 relative">

      {/* Sidebar - Desktop (lg) / Hidden on Mobile by default */}
      <div className={`
        fixed inset-0 lg:relative lg:inset-auto z-50 lg:z-30 
        w-full lg:w-96 glass p-6 flex flex-col gap-6 shadow-2xl overflow-y-auto scrollbar-hide
        transition-transform duration-300 ease-in-out
        ${showMobileSidebar ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}
      `}>
        {/* Mobile Close Button */}
        <button 
          onClick={() => setShowMobileSidebar(false)}
          className="lg:hidden absolute top-6 right-6 text-slate-400 hover:text-white p-2"
        >
          <i className="fas fa-times text-xl"></i>
        </button>

        <div className="flex items-center gap-3 mb-2">
          <div className="bg-amber-500 p-2.5 rounded-xl shadow-lg shadow-amber-500/20">
            <i className="fas fa-limousine text-slate-950 text-xl"></i>
          </div>
          <div>
            <h1 className="text-xl font-black text-white tracking-tighter">MILE HIGH</h1>
            <p className="text-[10px] text-amber-500 font-bold uppercase tracking-[0.2em]">Predictive Logistics</p>
          </div>
        </div>

        <form onSubmit={handleRouteRequest} className="flex flex-col gap-5">
          <div className="space-y-4">
            <div className="flex flex-col gap-1.5">
              <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest ml-1">Dispatch Start</label>
              <div className="relative group">
                <i className="fas fa-circle-dot absolute left-3 top-1/2 -translate-y-1/2 text-emerald-500 text-[10px]"></i>
                <input 
                  type="text" 
                  value={origin}
                  onChange={(e) => setOrigin(e.target.value)}
                  className="w-full bg-slate-900/80 border border-slate-800 rounded-xl py-3 pl-10 pr-4 text-sm focus:outline-none focus:ring-2 focus:ring-amber-500/30 transition-all"
                  placeholder="Enter pickup point..."
                />
              </div>
            </div>

            <div className="flex flex-col gap-1.5">
              <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest ml-1">Client Destination</label>
              <div className="relative group">
