}

export interface MapPoint {
  lat: number;
  lng: number;
  label: string;
  type: 'incident' | 'risk' | 'origin' | 'destination' | 'enforcement';
}

export interface OptimizedAlternative {
  timeSaved: string;
  description: string;
  fullAnalysis: string;
}

export interface TravelStats {
  estimatedTime: string;
  distance: string;
  tolls: string;
}

export interface RouteResponse {
  text: string;
  sources: { title: string; url: string }[];
  timestamp: string;
  mapData?: MapPoint[];
  alternative?: OptimizedAlternative;
  travelStats?: TravelStats;
}

export interface SavedRoute extends RouteResponse {
  id: string;
  origin: string;
  destination: string;
  date: string;
}

export interface TrafficIncident {
  id: string;
