    setAlternativePrompt(null);
    if (sr.mapData) updateMapData(sr.mapData);
    setShowMobileSidebar(false);
    setShowHistory(false);
  };

  const deleteSavedRoute = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    const updated = savedRoutes.filter(r => r.id !== id);
    setSavedRoutes(updated);
    localStorage.setItem('mile_high_routes', JSON.stringify(updated));
  };

  const handleRefreshTraffic = async () => {
    if (!location) return;
    setLoading(true);
    try {
      const feed = await gemini.current.monitorColoradoTraffic(location);
      setTrafficFeed(feed);
      if (feed.mapData) updateMapData(feed.mapData);
