import { GoogleGenAI } from "@google/genai";
import { Location, RouteResponse, MapPoint, OptimizedAlternative, TravelStats } from "../types";

export class GeminiService {
  private ai: GoogleGenAI;

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
  }

  private extractMapData(text: string): MapPoint[] {
    const mapData: MapPoint[] = [];
    const regex = /\[MAP_POINT:\s*([^,]+),\s*([^,]+),\s*([^,]+),\s*([^\]]+)\]/g;
    let match;
    while ((match = regex.exec(text)) !== null) {
      mapData.push({
        lat: parseFloat(match[1]),
        lng: parseFloat(match[2]),
        label: match[3].trim(),
        type: match[4].trim() as any
      });
    }
    return mapData;
  }

  private extractAlternative(text: string): { alternative?: OptimizedAlternative, cleanedText: string } {
    const regex = /\[OPTIMIZED_ROUTE:\s*([^,]+),\s*([^,]+),\s*([\s\S]*?)\]/;
    const match = text.match(regex);

    if (match) {
      const alt: OptimizedAlternative = {
        timeSaved: match[1].trim(),
        description: match[2].trim(),
        fullAnalysis: match[3].trim()
      };
      const cleanedText = text.replace(regex, '').trim();
      return { alternative: alt, cleanedText };
    }

    return { cleanedText: text };
  }

  private extractTravelStats(text: string): { stats?: TravelStats, cleanedText: string } {
    const regex = /\[TRAVEL_STATS:\s*([^,]+),\s*([^,]+),\s*([^\]]+)\]/;
    const match = text.match(regex);

    if (match) {
      const stats: TravelStats = {
        estimatedTime: match[1].trim(),
        distance: match[2].trim(),
        tolls: match[3].trim()
      };
      const cleanedText = text.replace(regex, '').trim();
      return { stats, cleanedText };
    }

    return { cleanedText: text };
  }

  async getBestRoute(
    origin: string,
    destination: string,
    currentLocation?: Location
  ): Promise<RouteResponse> {
    const timeOfDay = new Date().toLocaleTimeString();
    const dayOfWeek = new Date().toLocaleDateString('en-US', { weekday: 'long' });

    const prompt = `As an elite Colorado limo navigator, analyze the route from "${origin}" to "${destination}". 
    It is currently ${dayOfWeek} at ${timeOfDay}.

    1. REAL-TIME DATA: Use Google Maps grounding to identify active accidents, construction, and heavy traffic on I-70, I-25, and local arteries.
    2. PREDICTIVE ANALYSIS: Identify specific "High Risk" zones.
    3. ENFORCEMENT AWARENESS: Identify common speed traps and police hiding spots. 
       For each ENFORCEMENT map point, the label MUST categorize the tactic using one of these terms: 'Radar Speed Trap', 'Concealed Patrol Car', or 'Timing Light Enforcement', followed by the specific location details (e.g. "Concealed Patrol Car - hidden behind concrete bridge pillar").
    4. OPTIMIZATION CHECK: Analyze alternative routes. If a faster route exists that saves > 5 minutes, you MUST provide it.
    5. LOGISTICS: Provide estimated travel time, total distance, and specific toll information.

    FORMATTING RULES:
    - Use "### SECTION NAME" for headers.
    - Use numbered lists (1. 2. 3.) for the "RECOMMENDED ROUTE" steps.
    - Use bullet points (•) for "CURRENT INCIDENTS", "PREDICTIVE RISK ALERTS", and "SPEED ENFORCEMENT ZONES".

    IMPORTANT SPECIAL FORMATTING (MANDATORY):
    - Include travel statistics in this exact block: [TRAVEL_STATS: estimated_time, distance, toll_info]
    - If a faster alternative exists, include this block: [OPTIMIZED_ROUTE: time_saved, short_summary, full_alternative_analysis_text]
    - Format map points: [MAP_POINT: lat, lng, label, type] 

    Structure your response with:
    ### RECOMMENDED ROUTE
    ### CURRENT INCIDENTS
    ### PREDICTIVE RISK ALERTS
    ### SPEED ENFORCEMENT ZONES`;

    try {
      const config: any = {
        tools: [{ googleMaps: {} }],
      };

      if (currentLocation) {
        config.toolConfig = {
          retrievalConfig: {
            latLng: {
              latitude: currentLocation.latitude,
              longitude: currentLocation.longitude,
            },
          },
        };
      }

      const response = await this.ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: prompt,
        config: config,
      });

      const fullText = response.text || "Unable to retrieve route data.";
      const mapData = this.extractMapData(fullText);
      const { stats, cleanedText: textAfterStats } = this.extractTravelStats(fullText);
      const { alternative, cleanedText: textAfterAlt } = this.extractAlternative(textAfterStats);
      const cleanedText = textAfterAlt.replace(/\[MAP_POINT:[^\]]+\]/g, '').trim();

      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
      const sources = chunks
        .filter((chunk: any) => chunk.maps)
        .map((chunk: any) => ({
          title: chunk.maps.title,
          url: chunk.maps.uri,
        }));

      return {
        text: cleanedText,
        sources,
        timestamp: new Date().toLocaleTimeString(),
        mapData,
        alternative,
        travelStats: stats
      };
    } catch (error) {
      console.error("Gemini API Error:", error);
      throw new Error("Failed to fetch traffic data.");
    }
  }

  async monitorColoradoTraffic(location: Location): Promise<RouteResponse> {
    const prompt = `Provide a situational awareness report for a professional driver in Colorado. 
    Use Google Maps grounding for current delays and enforcement. 
    For ENFORCEMENT spots, the label MUST categorize the tactic (e.g. Radar Speed Trap, Concealed Patrol, Timing Light Enforcement).
    Include [MAP_POINT: lat, lng, label, type]`;

    try {
      const response = await this.ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: prompt,
        config: {
          tools: [{ googleMaps: {} }],
          toolConfig: {
            retrievalConfig: {
              latLng: location,
            },
          },
        },
      });

      const fullText = response.text || "No major incidents reported.";
      const mapData = this.extractMapData(fullText);
      const cleanedText = fullText.replace(/\[MAP_POINT:[^\]]+\]/g, '').trim();

      return {
        text: cleanedText,
        sources: [],
        timestamp: new Date().toLocaleTimeString(),
        mapData
      };
    } catch (error) {
      console.error("Gemini Monitor Error:", error);
      throw new Error("Failed to monitor traffic.");
    }
  }
}

import React, { useState, useEffect, useRef } from 'react';
