            </div>
            <div class="bg-blue-500/10 rounded-xl p-3 border border-blue-500/20">
              <p class="text-[9px] font-black text-blue-400 uppercase tracking-widest mb-1.5 flex items-center gap-1.5">
                <i class="fas fa-triangle-exclamation text-[8px]"></i> Limo Protocol
              </p>
              <p class="text-[10px] text-slate-400 leading-snug">
                Maintain 2mph below limit. Disable cruise control. No unnecessary lane shifts. Proximity alert locked.
              </p>
            </div>
          </div>
        `;

        marker.bindPopup(popupContent, {
          className: 'police-popup',
