export default Dashboard;

export interface Location {
  latitude: number;
  longitude: number;
}

export interface MapPoint {
  lat: number;
  lng: number;
  label: string;
  type: 'incident' | 'risk' | 'origin' | 'destination' | 'enforcement' | 'congestion';
}

export interface OptimizedAlternative {
  timeSaved: string;
  description: string;
  fullAnalysis: string;
}

export interface TravelStats {
  estimatedTime: string;
  distance: string;
  tolls: string;
}

export interface RouteResponse {
  text: string;
  sources: { title: string; url: string }[];
  timestamp: string;
  mapData?: MapPoint[];
  alternative?: OptimizedAlternative;
  travelStats?: TravelStats;
}

export interface SavedRoute extends RouteResponse {
  id: string;
  origin: string;
  destination: string;
  date: string;
}

export interface TrafficIncident {
  id: string;
  type: 'accident' | 'traffic' | 'weather';
  location: string;
  severity: 'low' | 'medium' | 'high';
  description: string;
}

import { GoogleGenAI } from "@google/genai";
import { Location, RouteResponse, MapPoint, OptimizedAlternative, TravelStats } from "../types";

export class GeminiService {
  private ai: GoogleGenAI;

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
  }

  private extractMapData(text: string): MapPoint[] {
    const mapData: MapPoint[] = [];
    const regex = /\[MAP_POINT:\s*([^,]+),\s*([^,]+),\s*([^,]+),\s*([^\]]+)\]/g;
    let match;
    while ((match = regex.exec(text)) !== null) {
      mapData.push({
        lat: parseFloat(match[1]),
        lng: parseFloat(match[2]),
        label: match[3].trim(),
        type: match[4].trim() as any
      });
    }
    return mapData;
  }

  private extractAlternative(text: string): { alternative?: OptimizedAlternative, cleanedText: string } {
    const regex = /\[OPTIMIZED_ROUTE:\s*([^,]+),\s*([^,]+),\s*([\s\S]*?)\]/;
    const match = text.match(regex);

    if (match) {
      const alt: OptimizedAlternative = {
        timeSaved: match[1].trim(),
        description: match[2].trim(),
        fullAnalysis: match[3].trim()
      };
      const cleanedText = text.replace(regex, '').trim();
      return { alternative: alt, cleanedText };
    }

    return { cleanedText: text };
  }

  private extractTravelStats(text: string): { stats?: TravelStats, cleanedText: string } {
    const regex = /\[TRAVEL_STATS:\s*([^,]+),\s*([^,]+),\s*([^\]]+)\]/;
    const match = text.match(regex);

    if (match) {
      const stats: TravelStats = {
        estimatedTime: match[1].trim(),
        distance: match[2].trim(),
        tolls: match[3].trim()
      };
      const cleanedText = text.replace(regex, '').trim();
      return { stats, cleanedText };
    }

    return { cleanedText: text };
  }

  async getBestRoute(
    origin: string,
    destination: string,
    currentLocation?: Location
  ): Promise<RouteResponse> {
    const timeOfDay = new Date().toLocaleTimeString();
    const dayOfWeek = new Date().toLocaleDateString('en-US', { weekday: 'long' });

    const prompt = `As an elite Colorado limo navigator, analyze the route from "${origin}" to "${destination}". 
    It is currently ${dayOfWeek} at ${timeOfDay}.

    1. REAL-TIME DATA: Use Google Maps grounding to identify active accidents, construction, and heavy traffic on I-70, I-25, and local arteries.
    2. PREDICTIVE ANALYSIS: Identify specific "High Risk" zones.
    3. ENFORCEMENT AWARENESS: Identify common speed traps and police hiding spots. 
       For each ENFORCEMENT map point, the label MUST categorize the tactic using one of these terms: 'Radar Speed Trap', 'Concealed Patrol Car', or 'Timing Light Enforcement', followed by the specific location details (e.g. "Concealed Patrol Car - hidden behind concrete bridge pillar").
    4. OPTIMIZATION CHECK: Analyze alternative routes. If a faster route exists that saves > 5 minutes, you MUST provide it.
    5. LOGISTICS: Provide estimated travel time, total distance, and specific toll information.
    6. VISUAL CONGESTION CUES: Identify 2-3 specific points of heavy traffic or slowdowns along the path. These will be rendered as advisory icons.

    FORMATTING RULES:
    - Use "### SECTION NAME" for headers.
    - Use numbered lists (1. 2. 3.) for the "RECOMMENDED ROUTE" steps.
    - Use bullet points (•) for "CURRENT INCIDENTS", "PREDICTIVE RISK ALERTS", and "SPEED ENFORCEMENT ZONES".

    IMPORTANT SPECIAL FORMATTING (MANDATORY):
    - Include travel statistics in this exact block: [TRAVEL_STATS: estimated_time, distance, toll_info]
    - If a faster alternative exists, include this block: [OPTIMIZED_ROUTE: time_saved, short_summary, full_alternative_analysis_text]
    - Format map points: [MAP_POINT: lat, lng, label, type] 
      (Types: incident, risk, origin, destination, enforcement, congestion)

    Structure your response with:
    ### RECOMMENDED ROUTE
    ### CURRENT INCIDENTS
    ### PREDICTIVE RISK ALERTS
    ### SPEED ENFORCEMENT ZONES`;

    try {
      const config: any = {
        tools: [{ googleMaps: {} }],
      };

      if (currentLocation) {
        config.toolConfig = {
          retrievalConfig: {
            latLng: {
              latitude: currentLocation.latitude,
              longitude: currentLocation.longitude,
            },
          },
        };
      }

      const response = await this.ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: prompt,
        config: config,
      });

      const fullText = response.text || "Unable to retrieve route data.";
      const mapData = this.extractMapData(fullText);
      const { stats, cleanedText: textAfterStats } = this.extractTravelStats(fullText);
      const { alternative, cleanedText: textAfterAlt } = this.extractAlternative(textAfterStats);
      const cleanedText = textAfterAlt.replace(/\[MAP_POINT:[^\]]+\]/g, '').trim();

      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
      const sources = chunks
        .filter((chunk: any) => chunk.maps)
        .map((chunk: any) => ({
          title: chunk.maps.title,
          url: chunk.maps.uri,
        }));

      return {
        text: cleanedText,
        sources,
        timestamp: new Date().toLocaleTimeString(),
        mapData,
        alternative,
        travelStats: stats
      };
    } catch (error) {
      console.error("Gemini API Error:", error);
      throw new Error("Failed to fetch traffic data.");
    }
  }

  async monitorColoradoTraffic(location: Location): Promise<RouteResponse> {
    const prompt = `Provide a situational awareness report for a professional driver in Colorado. 
    Use Google Maps grounding for current delays and enforcement. 
    For ENFORCEMENT spots, the label MUST categorize the tactic (e.g. Radar Speed Trap, Concealed Patrol, Timing Light Enforcement).
    Include [MAP_POINT: lat, lng, label, type] where type can also be 'congestion'.`;

    try {
      const response = await this.ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: prompt,
        config: {
          tools: [{ googleMaps: {} }],
          toolConfig: {
            retrievalConfig: {
              latLng: location,
            },
          },
        },
      });

      const fullText = response.text || "No major incidents reported.";
      const mapData = this.extractMapData(fullText);
      const cleanedText = fullText.replace(/\[MAP_POINT:[^\]]+\]/g, '').trim();

      return {
        text: cleanedText,
        sources: [],
        timestamp: new Date().toLocaleTimeString(),
        mapData
      };
    } catch (error) {
      console.error("Gemini Monitor Error:", error);
      throw new Error("Failed to monitor traffic.");
    }
  }
}

import React, { useState, useEffect, useRef } from 'react';
import { GeminiService } from '../services/geminiService';
import { Location, RouteResponse, MapPoint, SavedRoute, OptimizedAlternative, TravelStats } from '../types';

declare const L: any;

const FormattedAnalysis: React.FC<{ text: string }> = ({ text }) => {
  const lines = text.split('\n');

  return (
    <div className="space-y-3 break-words overflow-hidden w-full">
      {lines.map((line, idx) => {
        const trimmed = line.trim();
        if (!trimmed) return <div key={idx} className="h-1" />;

        if (trimmed.startsWith('###') || (trimmed.endsWith(':') && trimmed === trimmed.toUpperCase())) {
          const headerText = trimmed.replace(/^###\s*/, '');
          const isEnforcement = headerText.includes('ENFORCEMENT') || headerText.includes('POLICE');
          return (
            <h4 key={idx} className={`text-xs font-black uppercase tracking-[0.2em] mt-4 border-b pb-1 ${isEnforcement ? 'text-blue-500 border-blue-500/20' : 'text-amber-500 border-amber-500/10'}`}>
              {headerText}
            </h4>
          );
        }

        const numMatch = trimmed.match(/^(\d+)\.\s+(.*)/);
        if (numMatch) {
          return (
            <div key={idx} className="flex gap-3 items-start group">
              <span className="flex-shrink-0 w-5 h-5 rounded-full bg-slate-800 text-amber-500 text-[10px] font-bold flex items-center justify-center border border-slate-700 mt-0.5">
                {numMatch[1]}
              </span>
              <p className="text-[11px] leading-relaxed text-slate-300">
                {numMatch[2]}
              </p>
            </div>
          );
        }

        if (trimmed.startsWith('•') || trimmed.startsWith('-') || trimmed.startsWith('*')) {
          return (
            <div key={idx} className="flex gap-3 items-start pl-1">
              <span className="text-amber-500 mt-1 flex-shrink-0">•</span>
              <p className="text-[11px] leading-relaxed text-slate-400">
                {trimmed.replace(/^[•\-*]\s*/, '')}
              </p>
            </div>
          );
        }

        return (
          <p key={idx} className="text-[11px] leading-relaxed text-slate-300 pl-1">
            {trimmed}
          </p>
        );
      })}
    </div>
  );
};

const Dashboard: React.FC = () => {
  const [origin, setOrigin] = useState('Denver International Airport');
  const [destination, setDestination] = useState('Downtown Denver');
  const [loading, setLoading] = useState(false);
  const [routeResult, setRouteResult] = useState<RouteResponse | null>(null);
  const [location, setLocation] = useState<Location | null>(null);
  const [trafficFeed, setTrafficFeed] = useState<RouteResponse | null>(null);
  const [showMobileSidebar, setShowMobileSidebar] = useState(false);
  const [savedRoutes, setSavedRoutes] = useState<SavedRoute[]>([]);
  const [showHistory, setShowHistory] = useState(false);
  const [alternativePrompt, setAlternativePrompt] = useState<OptimizedAlternative | null>(null);

  const gemini = useRef(new GeminiService());
  const mapRef = useRef<any>(null);
  const mapMarkers = useRef<any[]>([]);
  const mapLayers = useRef<any[]>([]);

  // Initialize Map
  useEffect(() => {
    if (!mapRef.current) {
      mapRef.current = L.map('map', {
        zoomControl: false,
        attributionControl: false
      }).setView([39.7392, -104.9903], 10);

      L.tileLayer('https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png', {
        maxZoom: 19
      }).addTo(mapRef.current);

      L.control.zoom({ position: 'bottomright' }).addTo(mapRef.current);
    }

    const stored = localStorage.getItem('mile_high_routes');
    if (stored) {
      try {
        setSavedRoutes(JSON.parse(stored));
      } catch (e) {
        console.error("Failed to parse saved routes", e);
      }
    }
  }, []);

  // Get Current Location
  useEffect(() => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (pos) => {
          const newLoc = { latitude: pos.coords.latitude, longitude: pos.coords.longitude };
          setLocation(newLoc);
          if (mapRef.current) {
            mapRef.current.setView([newLoc.latitude, newLoc.longitude], 12);
            L.circle([newLoc.latitude, newLoc.longitude], {
              color: '#10b981',
              fillColor: '#10b981',
              fillOpacity: 0.2,
              radius: 500
            }).addTo(mapRef.current);
          }
        },
        (err) => console.warn("Location access denied", err)
      );
    }
  }, []);

  const updateMapData = (points: MapPoint[]) => {
    if (!mapRef.current) return;

    mapMarkers.current.forEach(m => mapRef.current.removeLayer(m));
    mapLayers.current.forEach(l => mapRef.current.removeLayer(l));
    mapMarkers.current = [];
    mapLayers.current = [];

    const bounds = L.latLngBounds([]);

    points.forEach(point => {
      const pos = [point.lat, point.lng];
      bounds.extend(pos);

      let marker;
      if (point.type === 'incident') {
        const pulseIcon = L.divIcon({
          className: 'custom-pulse-marker',
          iconSize: [14, 14],
          iconAnchor: [7, 7]
        });
        marker = L.marker(pos, { icon: pulseIcon }).addTo(mapRef.current);
        marker.bindPopup(`<div class="p-1"><b class="text-rose-500 block mb-1">ACCIDENT ALERT</b><span class="text-slate-700 text-xs">${point.label}</span></div>`);
      } else if (point.type === 'congestion') {
        const congestionIcon = L.divIcon({
          className: 'congestion-marker',
          iconSize: [12, 12],
          iconAnchor: [6, 6]
        });
        marker = L.marker(pos, { icon: congestionIcon }).addTo(mapRef.current);
        marker.bindPopup(`<div class="p-1 flex flex-col gap-1 min-w-[150px]">
          <div class="flex items-center gap-1.5 border-b border-orange-500/20 pb-1 mb-1">
            <i class="fas fa-gauge-low text-orange-500 text-[10px]"></i>
            <b class="text-orange-500 text-[10px] font-black uppercase">Traffic Advisory</b>
          </div>
          <span class="text-slate-300 text-[10px] leading-tight font-medium">${point.label}</span>
        </div>`);
      } else if (point.type === 'enforcement') {
        const policeIcon = L.divIcon({
          className: 'enforcement-pulse-marker',
          iconSize: [18, 18],
          iconAnchor: [9, 9]
        });
        marker = L.marker(pos, { icon: policeIcon }).addTo(mapRef.current);

        const lowerLabel = point.label.toLowerCase();
        let tacticIcon = 'fa-shield-halved';
        if (lowerLabel.includes('radar')) tacticIcon = 'fa-satellite-dish';
        if (lowerLabel.includes('concealed') || lowerLabel.includes('car')) tacticIcon = 'fa-car-on';
        if (lowerLabel.includes('light') || lowerLabel.includes('timing')) tacticIcon = 'fa-traffic-light';

        const popupContent = `
          <div class="flex flex-col gap-3 min-w-[220px]">
            <div class="flex items-center justify-between border-b border-blue-500/30 pb-2">
              <div class="flex items-center gap-2">
                <i class="fas ${tacticIcon} text-blue-400 text-sm"></i>
                <b class="text-blue-500 text-[10px] font-black uppercase tracking-widest">Patrol Intelligence</b>
              </div>
              <span class="text-[8px] bg-blue-500/20 text-blue-400 px-1.5 py-0.5 rounded-md font-black uppercase">Active</span>
            </div>
            <div class="py-1">
              <p class="text-white text-[12px] font-bold leading-tight mb-1">Tactical Analysis:</p>
              <p class="text-slate-300 text-[11px] leading-relaxed italic">"${point.label}"</p>
            </div>
            <div class="bg-blue-500/10 rounded-xl p-3 border border-blue-500/20">
              <p class="text-[9px] font-black text-blue-400 uppercase tracking-widest mb-1.5 flex items-center gap-1.5">
                <i class="fas fa-triangle-exclamation text-[8px]"></i> Limo Protocol
              </p>
              <p class="text-[10px] text-slate-400 leading-snug">
                Maintain 2mph below limit. Disable cruise control. No unnecessary lane shifts. Proximity alert locked.
              </p>
            </div>
          </div>
        `;

        marker.bindPopup(popupContent, {
          className: 'police-popup',
          maxWidth: 300
        });
      } else if (point.type === 'risk') {
        const riskCircle = L.circle(pos, {
          color: '#f59e0b',
          fillColor: '#f59e0b',
          fillOpacity: 0.1,
          radius: 1500,
          weight: 1,
          dashArray: '5, 5'
        }).addTo(mapRef.current);

        const rippleIcon = L.divIcon({
          className: 'risk-ripple-marker',
          iconSize: [10, 10],
          iconAnchor: [5, 5]
        });
        const rippleMarker = L.marker(pos, { icon: rippleIcon }).addTo(mapRef.current);
        riskCircle.bindPopup(`<div class="p-1"><b class="text-amber-500 block mb-1">RISK ZONE</b><span class="text-slate-700 text-xs">${point.label}</span></div>`);
        mapLayers.current.push(riskCircle);
        mapLayers.current.push(rippleMarker);
        return;
      } else if (point.type === 'origin') {
        marker = L.circleMarker(pos, {
          radius: 8,
          fillColor: "#10b981",
          color: "#fff",
          weight: 2,
          opacity: 1,
          fillOpacity: 0.8
        }).addTo(mapRef.current);
      } else if (point.type === 'destination') {
        marker = L.marker(pos, {
          icon: L.divIcon({
            html: '<i class="fas fa-location-dot text-rose-500 text-2xl drop-shadow-md"></i>',
            className: 'bg-transparent',
            iconSize: [20, 30],
            iconAnchor: [10, 30]
          })
        }).addTo(mapRef.current);
      }

      if (marker) mapMarkers.current.push(marker);
    });

    if (points.length > 0) {
      mapRef.current.fitBounds(bounds, { padding: [40, 40], maxZoom: 14 });
    }
  };

  const handleRouteRequest = async (e: React.FormEvent) => {
