  const [showMobileSidebar, setShowMobileSidebar] = useState(false);
  const [savedRoutes, setSavedRoutes] = useState<SavedRoute[]>([]);
  const [showHistory, setShowHistory] = useState(false);
  const [alternativePrompt, setAlternativePrompt] = useState<OptimizedAlternative | null>(null);
  const [isDeviated, setIsDeviated] = useState(false);
  const [notifications, setNotifications] = useState<{id: string, text: string, type: string}[]>([]);
  const [isScanning, setIsScanning] = useState(false);
  const [selectedPoint, setSelectedPoint] = useState<MapPoint | null>(null);

  const gemini = useRef(new GeminiService());
  const mapRef = useRef<any>(null);
  const mapMarkers = useRef<any[]>([]);
  const mapLayers = useRef<any[]>([]);
  const lastAudioAlertTime = useRef<number>(0);
  const lastScanTime = useRef<number>(0);

  useEffect(() => {
    if (!mapRef.current) {
      mapRef.current = L.map('map', { zoomControl: false, attributionControl: false }).setView([39.7392, -104.9903], 10);
      L.tileLayer('https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png', { maxZoom: 19 }).addTo(mapRef.current);
      L.control.zoom({ position: 'bottomright' }).addTo(mapRef.current);
    }
    const stored = localStorage.getItem('mile_high_routes');
    if (stored) { try { setSavedRoutes(JSON.parse(stored)); } catch (e) {} }
  }, []);

  const addNotification = (text: string, type: string = 'info') => {
    const id = crypto.randomUUID();
    setNotifications(prev => [{ id, text, type }, ...prev].slice(0, 5));
    setTimeout(() => {
      setNotifications(prev => prev.filter(n => n.id !== id));
    }, 10000);
  };

  const triggerAudioWarning = (message: string) => {
    const now = Date.now();
    if (now - lastAudioAlertTime.current > 30000) {
      const utterance = new SpeechSynthesisUtterance(message);
      utterance.rate = 1.1;
      utterance.pitch = 0.85;
      window.speechSynthesis.speak(utterance);
      lastAudioAlertTime.current = now;
    }
  };

  const calculateDistance = (lat1: number, lon1: number, lat2: number, lon2: number) => {
    const R = 6371e3;
    const p1 = (lat1 * Math.PI) / 180;
    const p2 = (lat2 * Math.PI) / 180;
    const dPhi = ((lat2 - lat1) * Math.PI) / 180;
    const dLam = ((lon2 - lon1) * Math.PI) / 180;
    const a = Math.sin(dPhi / 2) ** 2 + Math.cos(p1) * Math.cos(p2) * Math.sin(dLam / 2) ** 2;
    return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  };

  const performBackgroundScan = async () => {
    if (!location || isScanning) return;

    const now = Date.now();
    setIsScanning(true);
    try {
      const result = await gemini.current.monitorColoradoTraffic(location);
      setTrafficFeed(result);
      lastScanTime.current = now;

      if (result.mapData && result.mapData.length > 0) {
        const latestAlert = result.mapData[0];
        addNotification(`Sector Update: ${latestAlert.label}`, latestAlert.type);
        if (latestAlert.type === 'incident' || latestAlert.type === 'enforcement') {
          triggerAudioWarning(`New tactical alert: ${latestAlert.label}`);
        }
      }
    } catch (e) {
      console.error("Background scan failed", e);
    } finally {
      setIsScanning(false);
    }
  };

  useEffect(() => {
    const scanInterval = 180000;
    const intervalId = setInterval(() => {
      if (Date.now() - lastScanTime.current > scanInterval) performBackgroundScan();
    }, 60000);
    return () => clearInterval(intervalId);
  }, [location, isScanning]);

  useEffect(() => {
    const allPoints: MapPoint[] = [];
    if (routeResult?.mapData) allPoints.push(...routeResult.mapData);
    if (trafficFeed?.mapData) {
      const routeKeys = new Set(routeResult?.mapData?.map(p => `${p.lat.toFixed(4)},${p.lng.toFixed(4)}`) || []);
      trafficFeed.mapData.forEach(p => {
        if (!routeKeys.has(`${p.lat.toFixed(4)},${p.lng.toFixed(4)}`)) {
          allPoints.push(p);
        }
      });
    }
    updateMapData(allPoints);
  }, [routeResult, trafficFeed]);

  useEffect(() => {
    let watchId: number;
    if (navigator.geolocation) {
      watchId = navigator.geolocation.watchPosition((pos) => {
        const newLoc = { latitude: pos.coords.latitude, longitude: pos.coords.longitude };
        setLocation(newLoc);
        if (routeResult?.mapData) {
          const pathPoints = routeResult.mapData.filter(p => ['waypoint', 'turn', 'origin', 'destination'].includes(p.type));
          if (pathPoints.length > 0) {
            const minDistance = Math.min(...pathPoints.map(p => calculateDistance(newLoc.latitude, newLoc.longitude, p.lat, p.lng)));
            const deviated = minDistance > 800;
            setIsDeviated(deviated);
            if (deviated) triggerAudioWarning("Off course. Tactical adjustment required.");
          }
        }
      }, null, { enableHighAccuracy: true });
    }
    return () => navigator.geolocation.clearWatch(watchId);
  }, [routeResult]);

  const updateMapData = (points: MapPoint[]) => {
    if (!mapRef.current) return;
    mapMarkers.current.forEach(m => mapRef.current.removeLayer(m));
    mapLayers.current.forEach(l => mapRef.current.removeLayer(l));
    mapMarkers.current = []; mapLayers.current = [];

    const bounds = L.latLngBounds([]);
    const pathCoords: any[] = [];

    // Determine overall route color based on the existence of incidents or heavy traffic
    let routeColor = '#fbbf24'; // Default Amber
    const hasMajorIncidents = points.some(p => p.type === 'incident');
    const hasCongestion = points.some(p => p.type === 'congestion');

    if (hasMajorIncidents) routeColor = '#ef4444'; // Red for heavy threat
    else if (hasCongestion) routeColor = '#f59e0b'; // Darker amber/orange for moderate
    else if (routeResult && points.length > 0) routeColor = '#10b981'; // Green for clear mission path

    points.forEach(point => {
      const pos = [point.lat, point.lng];
      bounds.extend(pos);
      if (['waypoint', 'turn', 'origin', 'destination'].includes(point.type)) pathCoords.push(pos);

      let marker;
      const createIcon = (className: string, html?: string) => L.divIcon({ className, html, iconSize: [20, 20], iconAnchor: [10, 10] });

      if (point.type === 'incident') {
        marker = L.marker(pos, { icon: createIcon('custom-pulse-marker') }).addTo(mapRef.current);
      } else if (point.type === 'construction') {
        marker = L.marker(pos, { icon: L.divIcon({ html: '<i class="fas fa-hard-hat text-orange-500 text-lg drop-shadow-md"></i>', className: 'bg-transparent', iconSize:[20,20], iconAnchor:[10,10] }) }).addTo(mapRef.current);
      } else if (point.type === 'enforcement') {
        marker = L.marker(pos, { icon: createIcon('enforcement-pulse-marker') }).addTo(mapRef.current);
      } else if (point.type === 'turn') {
        marker = L.marker(pos, { icon: L.divIcon({ html: `<i class="fas fa-diamond-turn-right text-[${routeColor}] text-lg drop-shadow-md"></i>`, className: 'bg-transparent', iconSize:[20,20], iconAnchor:[10,10] }) }).addTo(mapRef.current);
      } else if (point.type === 'waypoint') {
        marker = L.circleMarker(pos, { radius: 4, fillColor: routeColor, color: "#fff", weight: 1, fillOpacity: 0.8 }).addTo(mapRef.current);
      } else if (point.type === 'risk') {
        const riskCircle = L.circle(pos, { color: '#f59e0b', fillOpacity: 0.1, radius: 1000 }).addTo(mapRef.current);
        mapLayers.current.push(riskCircle);
      } else if (point.type === 'origin') {
        marker = L.circleMarker(pos, { radius: 6, fillColor: "#10b981", color: "#fff", weight: 2, fillOpacity: 1 }).addTo(mapRef.current);
      } else if (point.type === 'destination') {
        marker = L.marker(pos, { icon: L.divIcon({ html: '<i class="fas fa-location-dot text-rose-500 text-2xl"></i>', className: 'bg-transparent', iconSize: [20, 30], iconAnchor: [10, 30] }) }).addTo(mapRef.current);
      }

      if (marker) {
        marker.on('click', () => {
          setSelectedPoint(point);
          mapRef.current.panTo(pos);
        });
        mapMarkers.current.push(marker);
      }
    });

    if (pathCoords.length > 1) {
      // Glow layer for route
      const glowLine = L.polyline(pathCoords, { color: routeColor, weight: 12, opacity: 0.15 }).addTo(mapRef.current);
      // Main tactical polyline with flow animation
      const mainLine = L.polyline(pathCoords, { 
        color: routeColor, 
        weight: 5, 
        opacity: 0.9,
        className: 'route-animated' 
      }).addTo(mapRef.current);

      mapLayers.current.push(glowLine, mainLine);
    }

    if (points.length > 0 && !routeResult) {
      mapRef.current.fitBounds(bounds, { padding: [60, 60], maxZoom: 15 });
    } else if (points.length > 0 && routeResult) {
      mapRef.current.fitBounds(bounds, { padding: [80, 80] });
    }
  };

  const handleRouteRequest = async (e: FormEvent) => {
    e.preventDefault(); setLoading(true); setRouteResult(null); setAlternativePrompt(null); setIsDeviated(false); setSelectedPoint(null);
    try {
      const result = await gemini.current.getBestRoute(origin, destination, location || undefined);
      setRouteResult(result);
      if (result.alternative) setAlternativePrompt(result.alternative);
    } catch (error) { alert("Sector scan failed. Check comms."); }
    finally { setLoading(false); }
  };

  const handleSaveRoute = () => {
    if (!routeResult) return;
    const newSavedRoute: SavedRoute = {
      ...routeResult,
      id: crypto.randomUUID(),
      origin,
      destination,
      date: new Date().toLocaleDateString()
    };
    const updated = [newSavedRoute, ...savedRoutes].slice(0, 15);
    setSavedRoutes(updated);
    localStorage.setItem('mile_high_routes', JSON.stringify(updated));
    addNotification("Tactical route archived.", "info");
  };

  const deleteSavedRoute = (e: MouseEvent, id: string) => {
    e.stopPropagation();
    const updated = savedRoutes.filter(r => r.id !== id);
    setSavedRoutes(updated);
    localStorage.setItem('mile_high_routes', JSON.stringify(updated));
  };

  const handleReportEnforcement = () => {
    if (!location) return;
    const reportPoint: MapPoint = {
      lat: location.latitude,
      lng: location.longitude,
      label: "User Reported Enforcement",
      type: 'enforcement'
    };
    setTrafficFeed(prev => ({
      text: prev?.text || "",
      sources: prev?.sources || [],
      timestamp: new Date().toLocaleTimeString(),
      mapData: [...(prev?.mapData || []), reportPoint]
    }));
    addNotification("Tactical report logged in sector.", "enforcement");
    triggerAudioWarning("Reporting enforcement at current position.");
  };

  const loadSavedRoute = (sr: SavedRoute) => {
    setOrigin(sr.origin);
    setDestination(sr.destination);
    setRouteResult(sr);
    setAlternativePrompt(null);
    setSelectedPoint(null);
    setShowMobileSidebar(false);
    setShowHistory(false);
  };

  const confirmIntel = () => {
    if (!selectedPoint) return;
    addNotification("Tactical intel confirmed. Strengthening sector data.", "info");
    setSelectedPoint(null);
  };

  return (
    <div className="flex h-screen w-full bg-[#070b14] overflow-hidden text-slate-200 relative font-['Inter']">

      {/* Sidebar Overlay */}
      <div className={`fixed inset-0 lg:relative lg:inset-auto z-50 lg:z-30 w-full lg:w-[400px] glass p-8 flex flex-col gap-8 shadow-2xl transition-transform duration-500 ease-out ${showMobileSidebar ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <button onClick={() => setShowMobileSidebar(false)} className="lg:hidden absolute top-8 right-8 text-slate-400 p-2"><i className="fas fa-times text-xl"></i></button>

        <div className="flex items-center gap-4">
          <div className="bg-amber-500 p-3 rounded-2xl shadow-lg shadow-amber-500/20"><i className="fas fa-limousine text-slate-950 text-xl"></i></div>
          <div><h1 className="text-2xl font-black text-white tracking-tighter uppercase leading-none">Mile High</h1><p className="text-[10px] text-amber-500 font-black uppercase tracking-[0.2em] mt-1">Tactical Logistics</p></div>
        </div>

        <form onSubmit={handleRouteRequest} className="flex flex-col gap-4">
          <div className="space-y-4">
            <div className="relative group">
              <i className="fas fa-circle-dot absolute left-4 top-1/2 -translate-y-1/2 text-emerald-500 text-[10px]"></i>
              <input type="text" value={origin} onChange={(e) => setOrigin(e.target.value)} className="w-full bg-slate-900/50 border border-slate-800 rounded-2xl py-4 pl-12 pr-4 text-sm focus:ring-2 focus:ring-amber-500/30 transition-all outline-none" placeholder="Origin..." />
            </div>
            <div className="relative group">
              <i className="fas fa-location-crosshairs absolute left-4 top-1/2 -translate-y-1/2 text-rose-500 text-[10px]"></i>
              <input type="text" value={destination} onChange={(e) => setDestination(e.target.value)} className="w-full bg-slate-900/50 border border-slate-800 rounded-2xl py-4 pl-12 pr-4 text-sm focus:ring-2 focus:ring-amber-500/30 transition-all outline-none" placeholder="Destination..." />
            </div>
          </div>
          <button type="submit" disabled={loading} className="w-full bg-gradient-to-r from-amber-600 to-amber-500 hover:from-amber-500 hover:to-amber-400 text-slate-950 font-black py-5 rounded-2xl shadow-xl uppercase tracking-widest text-xs transition-all active:scale-[0.98]">
            {loading ? <i className="fas fa-radar fa-spin mr-2"></i> : <i className="fas fa-satellite mr-2"></i>}
            Analyze Mission
          </button>
        </form>

        <div className="flex-1 overflow-y-auto scrollbar-hide space-y-4 pr-1">
           <button onClick={() => setShowHistory(!showHistory)} className="w-full flex justify-between items-center p-4 bg-slate-900/30 rounded-2xl border border-slate-800 text-[10px] font-black uppercase tracking-widest hover:border-amber-500/30 transition-colors"><span>Archive Log</span><i className={`fas fa-chevron-${showHistory ? 'up' : 'down'}`}></i></button>
           {showHistory && savedRoutes.map(sr => (
             <div key={sr.id} onClick={() => loadSavedRoute(sr)} className="p-4 bg-slate-950/50 border border-slate-800 hover:border-amber-500/50 rounded-2xl cursor-pointer text-[10px] group transition-all relative">
               <div className="text-amber-500 font-black truncate max-w-[85%]">{sr.origin}</div>
               <div className="text-slate-400 font-medium truncate mt-1 max-w-[85%]">to {sr.destination}</div>
               <div className="text-slate-600 mt-2 flex justify-between font-bold items-center">
                 <span>{sr.date}</span>
                 <i className="fas fa-chevron-right group-hover:translate-x-1 transition-transform"></i>
               </div>
               <button onClick={(e) => deleteSavedRoute(e, sr.id)} className="absolute top-4 right-4 text-slate-700 hover:text-rose-500 opacity-0 group-hover:opacity-100 transition-all p-1">
                 <i className="fas fa-trash-can text-[12px]"></i>
               </button>
             </div>
           ))}
        </div>

        <div className="border-t border-slate-800/50 pt-6 text-[10px] flex justify-between items-center font-black tracking-[0.25em] text-slate-500">
          <span>CO PORTAL v5.0</span>
          <span className="flex items-center gap-2"><span className={`w-2 h-2 rounded-full animate-pulse shadow-[0_0_8px_rgba(16,185,129,0.5)] ${isScanning ? 'bg-amber-500' : 'bg-emerald-500'}`}></span>{isScanning ? 'SCANNING' : 'LINKED'}</span>
        </div>
      </div>

      {/* Main Interface */}
      <div className="flex-1 relative h-full">

        {/* HUD Elements */}
        <div className="absolute top-8 left-8 z-20 flex flex-col gap-4 pointer-events-none">
          <button onClick={() => setShowMobileSidebar(true)} className="lg:hidden glass p-5 rounded-2xl pointer-events-auto text-amber-500 shadow-2xl active:scale-90"><i className="fas fa-bars text-xl"></i></button>

          <div className={`glass px-6 py-4 rounded-3xl flex items-center gap-5 border-2 transition-all duration-700 pointer-events-auto shadow-2xl ${isDeviated ? 'border-rose-500 bg-rose-500/10' : 'border-emerald-500/20'}`}>
            <div className={`w-3 h-3 rounded-full ${isDeviated ? 'bg-rose-500 animate-ping' : 'bg-emerald-500 animate-pulse'}`}></div>
            <div className="flex flex-col">
              <span className="text-[9px] font-black text-slate-500 uppercase tracking-widest">Tracking Status</span>
              <span className={`text-sm font-black uppercase tracking-tight ${isDeviated ? 'text-rose-500' : 'text-emerald-500'}`}>{isDeviated ? 'PROTOCOL DEVIATION' : 'NOMINAL PATH'}</span>
            </div>
            {isDeviated && <i className="fas fa-triangle-exclamation text-rose-500 text-lg"></i>}
          </div>

          <button 
            onClick={handleReportEnforcement}
            className="glass px-6 py-4 rounded-3xl border border-blue-500/30 pointer-events-auto shadow-2xl flex items-center gap-4 group hover:bg-blue-500/10 transition-all"
          >
            <i className="fas fa-shield-halved text-blue-500 group-hover:scale-110 transition-transform"></i>
            <span className="text-[10px] font-black uppercase tracking-widest text-blue-400">Drop Sighting</span>
          </button>
        </div>

        {/* Tactical Ticker */}
        <div className="absolute top-8 right-8 z-20 flex flex-col gap-3 pointer-events-none items-end">
          {notifications.map(n => (
            <div key={n.id} className="glass px-5 py-3 rounded-2xl border border-slate-800 shadow-2xl animate-in slide-in-from-right-10 pointer-events-auto flex items-center gap-4 max-w-xs">
              <i className={`fas ${n.type === 'incident' ? 'fa-car-burst text-rose-500' : n.type === 'enforcement' ? 'fa-shield-halved text-blue-500' : 'fa-circle-info text-amber-500'} text-xs`}></i>
              <span className="text-[11px] font-bold text-slate-300 leading-tight">{n.text}</span>
            </div>
          ))}
        </div>

        <div id="map" className="w-full h-full z-10"></div>

        {/* Point Detail Card */}
        {selectedPoint && (
          <div className="absolute right-8 bottom-32 z-50 glass w-72 p-6 rounded-[2rem] shadow-2xl border-t-4 border-amber-500 animate-in zoom-in-95 pointer-events-auto">
            <div className="flex justify-between items-start mb-4">
              <div className="flex items-center gap-3">
                <i className={`fas ${selectedPoint.type === 'incident' ? 'fa-car-burst text-rose-500' : selectedPoint.type === 'enforcement' ? 'fa-shield-halved text-blue-500' : selectedPoint.type === 'hard-hat' || selectedPoint.type === 'construction' ? 'fa-hard-hat text-orange-500' : 'fa-info-circle text-amber-500'} text-lg`}></i>
                <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">{selectedPoint.type}</span>
              </div>
              <button onClick={() => setSelectedPoint(null)} className="text-slate-600 hover:text-white"><i className="fas fa-times"></i></button>
            </div>
            <h4 className="text-white font-black leading-tight mb-2">{selectedPoint.label}</h4>
            <div className="bg-slate-900/50 p-3 rounded-xl border border-slate-800 mb-4">
              <span className="text-[9px] font-black text-slate-500 uppercase block mb-1">Tactical Intel</span>
              <p className="text-[11px] text-slate-300 italic">"High density sector detected. Maintain operational awareness."</p>
            </div>
            <div className="flex flex-col gap-2">
              <button onClick={confirmIntel} className="w-full py-3 bg-emerald-500/10 hover:bg-emerald-500/20 border border-emerald-500/30 rounded-xl text-emerald-400 text-[10px] font-black uppercase tracking-widest transition-all">Verify Intel</button>
              <button onClick={() => setSelectedPoint(null)} className="w-full py-3 bg-slate-800/50 hover:bg-slate-800 rounded-xl text-slate-400 text-[10px] font-black uppercase tracking-widest transition-all">Dismiss</button>
            </div>
          </div>
        )}

        {/* Tactical Intel Drawer */}
        {routeResult && (
          <div className="absolute left-6 right-6 bottom-6 lg:left-10 lg:right-10 lg:bottom-10 z-40 glass p-8 lg:p-10 rounded-[3rem] shadow-[0_20px_60px_rgba(0,0,0,0.6)] border-l-[8px] border-amber-500 max-h-[55vh] overflow-y-auto scrollbar-hide animate-in slide-in-from-bottom-32 pointer-events-auto">

            <div className="flex justify-between items-start mb-8 sticky top-0 bg-[#0f172a]/95 py-2 z-20 backdrop-blur-md">
              <div className="flex items-center gap-4">
                <div className="p-3 bg-amber-500/10 rounded-2xl border border-amber-500/20">
                  <i className="fas fa-microchip text-amber-500 text-xl"></i>
                </div>
                <div>
                  <h3 className="text-lg font-black uppercase text-amber-500 tracking-tight">Mission Intelligence</h3>
                  <p className="text-[10px] text-slate-500 font-black uppercase tracking-[0.2em]">Telemetry v5.0 Output</p>
                </div>
              </div>
              <div className="flex gap-3">
                <button onClick={handleSaveRoute} className="p-3 bg-amber-500/10 hover:bg-amber-500/20 border border-amber-500/20 rounded-2xl text-amber-500 transition-colors" title="Save Tactical Route">
                  <i className="fas fa-bookmark"></i>
                </button>
                <button onClick={() => setRouteResult(null)} className="p-3 bg-white/5 hover:bg-white/10 rounded-2xl text-slate-500 transition-colors"><i className="fas fa-times"></i></button>
              </div>
            </div>

            {routeResult.travelStats && (
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-10">
                <div className="bg-slate-900/80 p-6 rounded-3xl border border-slate-800 flex items-center gap-5 shadow-inner">
                  <div className="text-amber-500 bg-amber-500/10 p-3 rounded-xl"><i className="fas fa-clock"></i></div>
                  <div><span className="text-[9px] font-black text-slate-500 uppercase tracking-widest">ETA Window</span><p className="text-lg font-black text-white">{routeResult.travelStats.estimatedTime}</p></div>
                </div>
                <div className="bg-slate-900/80 p-6 rounded-3xl border border-slate-800 flex items-center gap-5 shadow-inner">
                  <div className="text-emerald-500 bg-emerald-500/10 p-3 rounded-xl"><i className="fas fa-road"></i></div>
                  <div><span className="text-[9px] font-black text-slate-500 uppercase tracking-widest">Range</span><p className="text-lg font-black text-white">{routeResult.travelStats.distance}</p></div>
                </div>
                <div className="bg-slate-900/80 p-6 rounded-3xl border border-slate-800 flex items-center gap-5 shadow-inner">
                  <div className="text-blue-500 bg-blue-500/10 p-3 rounded-xl"><i className="fas fa-coins"></i></div>
                  <div><span className="text-[9px] font-black text-slate-500 uppercase tracking-widest">Tolls</span><p className="text-lg font-black text-white">{routeResult.travelStats.tolls}</p></div>
                </div>
              </div>
            )}

            <div className="pb-10">
              <FormattedAnalysis text={routeResult.text} />
            </div>

            {routeResult.sources.length > 0 && (
              <div className="border-t border-slate-800/50 pt-8 flex flex-wrap gap-3">
                {routeResult.sources.map((src, i) => (
                  <a key={i} href={src.url} target="_blank" rel="noopener noreferrer" className="px-5 py-2.5 bg-blue-500/5 hover:bg-blue-500/10 rounded-xl border border-blue-500/10 text-[10px] font-black text-blue-400 uppercase tracking-widest transition-all">
                    <i className="fas fa-link mr-2 text-[8px]"></i> {src.title}
                  </a>
                ))}
              </div>
            )}
          </div>
        )}
      </div>

      {loading && (
        <div className="fixed inset-0 z-[100] bg-slate-950/90 backdrop-blur-xl flex flex-col items-center justify-center">
          <div className="relative w-32 h-32 mb-10">
            <div className="absolute inset-0 border-[6px] border-amber-500/10 rounded-full"></div>
            <div className="absolute inset-0 border-[6px] border-t-amber-500 rounded-full animate-spin"></div>
            <div className="absolute inset-4 border-[6px] border-b-blue-500/40 rounded-full animate-spin-slow"></div>
            <i className="fas fa-dna absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 text-amber-500 text-3xl animate-pulse"></i>
          </div>
          <h2 className="text-white font-black uppercase text-xl tracking-[0.4em] mb-3">Syncing Area Grid</h2>
          <p className="text-slate-500 text-xs font-bold uppercase tracking-widest animate-pulse">Establishing Secure Uplink...</p>
        </div>
      )}
    </div>
  );
};

export default Dashboard;
